-- C11/P11.10 additive restore integrity evidence. Repository-only.
create table if not exists public.command_center_book_restore_history(
 owner_id uuid not null references auth.users(id) on delete cascade, restore_id text not null check(btrim(restore_id)<>''), export_manifest_id text not null, schema_version integer not null check(schema_version>0), compatible_schema_versions integer[] not null, book_ids text[] not null check(cardinality(book_ids)>0), artifact_ids text[] not null default '{}', publication_state_refs text[] not null default '{}', approval_state_refs text[] not null default '{}', protected_asset_ids text[] not null default '{}', superseded_state_refs text[] not null default '{}', revoked_authority_refs text[] not null default '{}', provider_migration_refs text[] not null default '{}', historical_source_refs text[] not null check(cardinality(historical_source_refs)>0), conflict_state text not null check(conflict_state in('none','requires_owner_resolution','resolved')), conflict_refs text[] not null default '{}', restored_at timestamptz not null, primary key(owner_id,restore_id)
);
create or replace function public.command_center_reject_book_restore_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Book restore evidence is immutable'; end $$;
create trigger command_center_book_restore_immutable before update or delete on public.command_center_book_restore_history for each row execute function public.command_center_reject_book_restore_mutation();
alter table public.command_center_book_restore_history enable row level security; revoke all on table public.command_center_book_restore_history from public,anon,authenticated; grant select,insert on table public.command_center_book_restore_history to authenticated;
create policy p11_10_book_restore_owner on public.command_center_book_restore_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
